function longestPalindromeSubseq(s) {
  const memo = new Map();                        // "i,j" -> answer for s[i..j]
  const lps = (i, j) => {                        // longest palindromic subsequence inside s[i..j]
    if (i > j) return 0;                         // empty range
    if (i === j) return 1;                       // one letter
    const key = i + "," + j;
    if (memo.has(key)) return memo.get(key);
    const best = s[i] === s[j] ? 2 + lps(i + 1, j - 1) : Math.max(lps(i + 1, j), lps(i, j - 1));
    memo.set(key, best);
    return best;
  };
  return lps(0, s.length - 1);
}

from functools import cache

def longest_palindrome_subseq(s):
    @cache
    def lps(i, j):                        # longest palindromic subsequence inside s[i..j]
        if i > j:
            return 0                      # empty range
        if i == j:
            return 1                      # one letter
        if s[i] == s[j]:
            return 2 + lps(i + 1, j - 1)  # both ends wrap the inside
        return max(lps(i + 1, j), lps(i, j - 1))   # drop one end

    return lps(0, len(s) - 1)

