int lps(String s, int i, int j) {                // longest palindromic subsequence inside s[i..j]
    if (i > j) return 0;                         // empty range
    if (i == j) return 1;                        // one letter
    if (memo[i][j] != null) return memo[i][j];
    int best = s.charAt(i) == s.charAt(j) ? 2 + lps(s, i + 1, j - 1) : Math.max(lps(s, i + 1, j), lps(s, i, j - 1));
    memo[i][j] = best;
    return best;
}

