function longestPalindromeSubseq(s) {
  const t = [...s].reverse().join("");           // a palindrome is in both s and its reverse
  const n = s.length;
  let prev = new Array(n + 1).fill(0);
  for (let i = 1; i <= n; i++) {
    const cur = new Array(n + 1).fill(0);
    for (let j = 1; j <= n; j++) {
      cur[j] = s[i - 1] === t[j - 1] ? prev[j - 1] + 1 : Math.max(prev[j], cur[j - 1]);
    }
    prev = cur;                                  // only the row above is needed
  }
  return prev[n];                                // the LCS of s and its reverse
}

